void Array_PfxBodyPropertiesEntry_init(Array_PfxBodyPropertiesEntry *obj) {
    obj->type_info_ = &Array_PfxBodyPropertiesEntry_TI;
    obj->count = 0;
    obj->items = NULL;
}

bool Array_PfxBodyPropertiesEntry_read(Array_PfxBodyPropertiesEntry *obj, Buffer* buffer) {
    uint32 count = 0;
    uint32 unk0 = 0;
    uint32 offset = 0;
    uint32 unk1 = 0;
    if (!uint32_read(&offset, buffer)) return false;
    if (!uint32_read(&unk0, buffer)) return false;
    if (!uint32_read(&count, buffer)) return false;
    if (!uint32_read(&unk1, buffer)) return false;
    obj->count = count;
    if(count>0){
       int64 original_offset = 0;
       obj->items = (PfxBodyPropertiesEntry*)mp_calloc(sizeof(PfxBodyPropertiesEntry), count);
       if(buffer->get_position(buffer, &original_offset)!=BUFFER_SUCCESS) return false;
       if(buffer->set_position(buffer, offset, BUFFER_ORIGIN_START)!=BUFFER_SUCCESS) return false;
       for (uint32 i = 0; i < count; ++i) {
           PfxBodyPropertiesEntry_init(&obj->items[i]);
           PfxBodyPropertiesEntry_read(&obj->items[i], buffer);
       }
       if(buffer->set_position(buffer, original_offset, BUFFER_ORIGIN_START)!=BUFFER_SUCCESS) return false;
    }
    return true;
}

void Array_PfxBodyPropertiesEntry_free(Array_PfxBodyPropertiesEntry *obj) {
    for (uint32 i = 0; i < obj->count; ++i) {
        PfxBodyPropertiesEntry_free(&obj->items[i]);
    }
    mp_free(obj->items);
}

void Array_PfxBodyPropertiesEntry_print(Array_PfxBodyPropertiesEntry *obj, JsonContext* ctx) {
    jsonBeginArray(ctx);
    for (uint32 i = 0; i < obj->count; ++i) {
        PfxBodyPropertiesEntry_print(&obj->items[i], ctx);
    }
    jsonEndArray(ctx);
}

