void Array_AttachSetting_init(Array_AttachSetting *obj) {
    obj->type_info_ = &Array_AttachSetting_TI;
    obj->count = 0;
    obj->items = NULL;
}

bool Array_AttachSetting_read(Array_AttachSetting *obj, Buffer* buffer) {
    uint32 count = 0;
    uint32 unk0 = 0;
    uint32 offset = 0;
    uint32 unk1 = 0;
    if (!uint32_read(&offset, buffer)) return false;
    if (!uint32_read(&unk0, buffer)) return false;
    if (!uint32_read(&count, buffer)) return false;
    if (!uint32_read(&unk1, buffer)) return false;
    obj->count = count;
    if(count>0){
       int64 original_offset = 0;
       obj->items = (AttachSetting*)mp_calloc(sizeof(AttachSetting), count);
       if(buffer->get_position(buffer, &original_offset)!=BUFFER_SUCCESS) return false;
       if(buffer->set_position(buffer, offset, BUFFER_ORIGIN_START)!=BUFFER_SUCCESS) return false;
       for (uint32 i = 0; i < count; ++i) {
           AttachSetting_init(&obj->items[i]);
           AttachSetting_read(&obj->items[i], buffer);
       }
       if(buffer->set_position(buffer, original_offset, BUFFER_ORIGIN_START)!=BUFFER_SUCCESS) return false;
    }
    return true;
}

void Array_AttachSetting_free(Array_AttachSetting *obj) {
    mp_free(obj->items);
}

void Array_AttachSetting_print(Array_AttachSetting *obj, JsonContext* ctx) {
    jsonBeginArray(ctx);
    for (uint32 i = 0; i < obj->count; ++i) {
        AttachSetting_print(&obj->items[i], ctx);
    }
    jsonEndArray(ctx);
}

