void GenericVehicleCamera_init(GenericVehicleCamera *obj) {
    obj->type_info_ = &GenericVehicleCamera_TI;
    CameraSpring_init(&obj->LagSpring);
    CameraSpring_init(&obj->CameraVelocitySpring);
    CameraSpring_init(&obj->LookAtVelocitySpring);
    CameraSpring_init(&obj->FOVBlendSpring);
    CameraSpring_init(&obj->CollisionBlendSpring);
    CameraSpring_init(&obj->CollisionPitchSpring);
    CameraTowing_init(&obj->TowingOffsets);
    InputStick_init(&obj->InputSettings);
    VehicleSplineFuncOfPitchParams_init(&obj->SplineFuncOfPitchParams);
}

bool GenericVehicleCamera_read(GenericVehicleCamera *obj, Buffer* buffer) {
    float32_read(&obj->StateTransitionTime, buffer);
    float32_read(&obj->TransitionToCrashStateDelay, buffer);
    float32_read(&obj->DriftTransitionTime, buffer);
    for(int i = 0; i < 3; ++i) {
        float32_read(&obj->CameraPosition[i], buffer);
    }
    for(int i = 0; i < 3; ++i) {
        float32_read(&obj->CrashingCameraPosition[i], buffer);
    }
    for(int i = 0; i < 3; ++i) {
        float32_read(&obj->RotationPoint[i], buffer);
    }
    for(int i = 0; i < 3; ++i) {
        float32_read(&obj->LookAtPoint[i], buffer);
    }
    float32_read(&obj->LookAtReferenceWheelbaseRatio, buffer);
    float32_read(&obj->AddLookAtPointToPositionRatio, buffer);
    float32_read(&obj->VelDirBlendWithVehicleDirSpeed, buffer);
    float32_read(&obj->DrivingVelocityMatrixBlend, buffer);
    float32_read(&obj->MinTimeForHalfTurn, buffer);
    float32_read(&obj->YawSpringStiffness, buffer);
    float32_read(&obj->DriftYawSpringStiffness, buffer);
    float32_read(&obj->YawSpringAngleLimit, buffer);
    float32_read(&obj->YawSpringLimitStiffnessPower, buffer);
    float32_read(&obj->YawSpringStiffnessMax, buffer);
    float32_read(&obj->PitchSpringStiffness, buffer);
    for(int i = 0; i < 2; ++i) {
        float32_read(&obj->PitchLimit[i], buffer);
    }
    float32_read(&obj->RollSpringStiffness, buffer);
    for(int i = 0; i < 2; ++i) {
        float32_read(&obj->RollLimit[i], buffer);
    }
    CameraSpring_read(&obj->LagSpring, buffer);
    float32_read(&obj->LagCameraRelativity, buffer);
    float32_read(&obj->LagVelocityScale, buffer);
    for(int i = 0; i < 2; ++i) {
        float32_read(&obj->FollowCameraRange[i], buffer);
    }
    CameraSpring_read(&obj->CameraVelocitySpring, buffer);
    CameraSpring_read(&obj->LookAtVelocitySpring, buffer);
    float32_read(&obj->UpCameraVelocityRefSpeedKph, buffer);
    for(int i = 0; i < 2; ++i) {
        float32_read(&obj->UpCameraRange[i], buffer);
    }
    float32_read(&obj->UpLookAtVelocityRefSpeedKph, buffer);
    for(int i = 0; i < 2; ++i) {
        float32_read(&obj->UpLookAtRange[i], buffer);
    }
    float32_read(&obj->RightCameraVelocityRefSpeedKph, buffer);
    for(int i = 0; i < 2; ++i) {
        float32_read(&obj->RightCameraRange[i], buffer);
    }
    float32_read(&obj->RightLookAtVelocityRefSpeedKph, buffer);
    for(int i = 0; i < 2; ++i) {
        float32_read(&obj->RightLookAtRange[i], buffer);
    }
    float32_read(&obj->RollWithVehicleAmount, buffer);
    float32_read(&obj->ReCenterDelay, buffer);
    float32_read(&obj->ReCenterSpeed, buffer);
    for(int i = 0; i < 2; ++i) {
        float32_read(&obj->FOVVelocityRange[i], buffer);
    }
    for(int i = 0; i < 2; ++i) {
        float32_read(&obj->FOV[i], buffer);
    }
    CameraSpring_read(&obj->FOVBlendSpring, buffer);
    float32_read(&obj->FOVZoomAdjustment, buffer);
    CameraSpring_read(&obj->CollisionBlendSpring, buffer);
    float32_read(&obj->CollisionFudgeFactor, buffer);
    uint8_read(&obj->CollisionPitchEnabled, buffer);
    buffer->skip(buffer, 3);
    CameraSpring_read(&obj->CollisionPitchSpring, buffer);
    float32_read(&obj->CollisionPitchDistance, buffer);
    uint32_read(&obj->CollisionCheckWater, buffer);
    for(int i = 0; i < 3; ++i) {
        float32_read(&obj->CollisionStartPoint[i], buffer);
    }
    CameraTowing_read(&obj->TowingOffsets, buffer);
    uint8_read(&obj->AlignReferenceWithWorldUp, buffer);
    buffer->skip(buffer, 3);
    uint32_read(&obj->DrawDebugInfo, buffer);
    float32_read(&obj->ListenerHeadRelativity, buffer);
    InputStick_read(&obj->InputSettings, buffer);
    VehicleSplineFuncOfPitchParams_read(&obj->SplineFuncOfPitchParams, buffer);
    return true;
}

