void Array_SplineAnimation_init(Array_SplineAnimation *obj) {
    obj->type_info_ = &Array_SplineAnimation_TI;
    obj->count = 0;
    obj->items = NULL;
}

bool Array_SplineAnimation_read(Array_SplineAnimation *obj, Buffer* buffer) {
    uint32 count = 0;
    uint32 unk0 = 0;
    uint32 offset = 0;
    uint32 unk1 = 0;
    if (!uint32_read(&offset, buffer)) return false;
    if (!uint32_read(&unk0, buffer)) return false;
    if (!uint32_read(&count, buffer)) return false;
    if (!uint32_read(&unk1, buffer)) return false;
    obj->count = count;
    if(count>0){
       int64 original_offset = 0;
       obj->items = (SplineAnimation*)mp_calloc(sizeof(SplineAnimation), count);
       if(buffer->get_position(buffer, &original_offset)!=BUFFER_SUCCESS) return false;
       if(buffer->set_position(buffer, offset, BUFFER_ORIGIN_START)!=BUFFER_SUCCESS) return false;
       for (uint32 i = 0; i < count; ++i) {
           SplineAnimation_init(&obj->items[i]);
           SplineAnimation_read(&obj->items[i], buffer);
       }
       if(buffer->set_position(buffer, original_offset, BUFFER_ORIGIN_START)!=BUFFER_SUCCESS) return false;
    }
    return true;
}

void Array_SplineAnimation_free(Array_SplineAnimation *obj) {
    for (uint32 i = 0; i < obj->count; ++i) {
        SplineAnimation_free(&obj->items[i]);
    }
    mp_free(obj->items);
}

void Array_SplineAnimation_print(Array_SplineAnimation *obj, JsonContext* ctx) {
    jsonBeginArray(ctx);
    for (uint32 i = 0; i < obj->count; ++i) {
        SplineAnimation_print(&obj->items[i], ctx);
    }
    jsonEndArray(ctx);
}

