void Array_BoneData_init(Array_BoneData *obj) {
    obj->type_info_ = &Array_BoneData_TI;
    obj->count = 0;
    obj->items = NULL;
}

bool Array_BoneData_read(Array_BoneData *obj, Buffer* buffer) {
    uint32 count = 0;
    uint32 unk0 = 0;
    uint32 offset = 0;
    uint32 unk1 = 0;
    if (!uint32_read(&offset, buffer)) return false;
    if (!uint32_read(&unk0, buffer)) return false;
    if (!uint32_read(&count, buffer)) return false;
    if (!uint32_read(&unk1, buffer)) return false;
    obj->count = count;
    if(count>0){
       int64 original_offset = 0;
       obj->items = (BoneData*)mp_calloc(sizeof(BoneData), count);
       if(buffer->get_position(buffer, &original_offset)!=BUFFER_SUCCESS) return false;
       if(buffer->set_position(buffer, offset, BUFFER_ORIGIN_START)!=BUFFER_SUCCESS) return false;
       for (uint32 i = 0; i < count; ++i) {
           BoneData_init(&obj->items[i]);
           BoneData_read(&obj->items[i], buffer);
       }
       if(buffer->set_position(buffer, original_offset, BUFFER_ORIGIN_START)!=BUFFER_SUCCESS) return false;
    }
    return true;
}

void Array_BoneData_free(Array_BoneData *obj) {
    for (uint32 i = 0; i < obj->count; ++i) {
        BoneData_free(&obj->items[i]);
    }
    mp_free(obj->items);
}

void Array_BoneData_print(Array_BoneData *obj, JsonContext* ctx) {
    jsonBeginArray(ctx);
    for (uint32 i = 0; i < obj->count; ++i) {
        BoneData_print(&obj->items[i], ctx);
    }
    jsonEndArray(ctx);
}

