void Part_init(Part *obj) {
    obj->type_info_ = &Part_TI;
    HashString_init(&obj->name);
    HashString_init(&obj->damage_type);
    HashString_init(&obj->behavior);
    HashString_init(&obj->model);
    HashString_init(&obj->model_swap);
    Array_int8_init(&obj->children_part_indices);
    Array_int16_init(&obj->hide_parts_when_broken);
    Array_int16_init(&obj->meshswap_parts_when_broken);
    Array_int16_init(&obj->loosen_parts_when_broken);
    Array_int16_init(&obj->break_parts_when_broken);
}

bool Part_read(Part *obj, Buffer* buffer) {
    HashString_read(&obj->name, buffer);
    HashString_read(&obj->damage_type, buffer);
    HashString_read(&obj->behavior, buffer);
    HashString_read(&obj->model, buffer);
    HashString_read(&obj->model_swap, buffer);
    int8_read(&obj->part_index, buffer);
    int8_read(&obj->parent_part_index, buffer);
    buffer->skip(buffer, 2);
    for(int i = 0; i < 16; ++i) {
        float32_read(&obj->parent_space_offset[i], buffer);
    }
    for(int i = 0; i < 16; ++i) {
        float32_read(&obj->bind_pose_bone_matrix[i], buffer);
    }
    buffer->skip(buffer, 4);
    Array_int8_read(&obj->children_part_indices, buffer);
    int8_read(&obj->starts_loose, buffer);
    int8_read(&obj->should_break, buffer);
    int8_read(&obj->prevent_mesh_swap_while_alive, buffer);
    int8_read(&obj->prevent_loosening_while_alive, buffer);
    int8_read(&obj->prevent_breaking_while_alive, buffer);
    int8_read(&obj->always_mesh_swap_on_death, buffer);
    int8_read(&obj->always_loosen_on_death, buffer);
    int8_read(&obj->always_break_on_death, buffer);
    int8_read(&obj->disappears_when_broken, buffer);
    int8_read(&obj->appears_on_death, buffer);
    int8_read(&obj->disappears_on_death, buffer);
    int8_read(&obj->starts_deleted, buffer);
    int8_read(&obj->is_deformable, buffer);
    int8_read(&obj->has_lights, buffer);
    int8_read(&obj->has_world_collision_shape, buffer);
    int8_read(&obj->only_collides_once_loose, buffer);
    int8_read(&obj->only_collides_once_broken, buffer);
    buffer->skip(buffer, 7);
    Array_int16_read(&obj->hide_parts_when_broken, buffer);
    Array_int16_read(&obj->meshswap_parts_when_broken, buffer);
    Array_int16_read(&obj->loosen_parts_when_broken, buffer);
    Array_int16_read(&obj->break_parts_when_broken, buffer);
    int16_read(&obj->world_collision_instance_id, buffer);
    int16_read(&obj->raycast_instance_id, buffer);
    int16_read(&obj->grandpa_world_instance_id, buffer);
    int16_read(&obj->grandpa_raycast_instance_id, buffer);
    int16_read(&obj->world_collision_body_id, buffer);
    int16_read(&obj->raycast_body_id, buffer);
    int16_read(&obj->constraint_index, buffer);
    buffer->skip(buffer, 2);
    for(int i = 0; i < 4; ++i) {
        float32_read(&obj->centroid[i], buffer);
    }
    for(int i = 0; i < 4; ++i) {
        float32_read(&obj->deformation_centroid_offset[i], buffer);
    }
    return true;
}

