void StuntArea_init(StuntArea *obj) {
    obj->type_info_ = &StuntArea_TI;
    AxisAlignedBoundingBox_init(&obj->bounding_box_local);
}

bool StuntArea_read(StuntArea *obj, Buffer* buffer) {
    String_read(&obj->name, buffer);
    uint32_read(&obj->name_hash, buffer);
    buffer->skip(buffer, 4);
    String_read(&obj->part_name, buffer);
    uint32_read(&obj->part_hash, buffer);
    uint32_read(&obj->part_index, buffer);
    for(int i = 0; i < 16; ++i) {
        uint32_read(&obj->deform_points[i], buffer);
    }
    for(int i = 0; i < 16; ++i) {
        uint8_read(&obj->edge_validity[i], buffer);
    }
    uint16_read(&obj->number_of_deform_points, buffer);
    uint16_read(&obj->active, buffer);
    for(int i = 0; i < 48; ++i) {
        float32_read(&obj->vertices3D_local[i], buffer);
    }
    for(int i = 0; i < 42; ++i) {
        uint8_read(&obj->triangle_indices[i], buffer);
    }
    uint16_read(&obj->number_of_triangles, buffer);
    AxisAlignedBoundingBox_read(&obj->bounding_box_local, buffer);
    for(int i = 0; i < 3; ++i) {
        float32_read(&obj->center_local[i], buffer);
    }
    buffer->skip(buffer, 4);
    return true;
}

void StuntArea_free(StuntArea *obj) {
    String_free(&obj->name);
    String_free(&obj->part_name);
}

