    uint32_print(&obj->name_hash, ctx);
    jsonName(ctx, "part_name");
    String_print(&obj->part_name, ctx);
    jsonName(ctx, "part_hash");
    uint32_print(&obj->part_hash, ctx);
    jsonName(ctx, "part_index");
    uint32_print(&obj->part_index, ctx);
    jsonName(ctx, "deform_points");
    jsonBeginCompactArray(ctx);
    for (uint32 i = 0; i < 16; ++i) {
        uint32_print(&obj->deform_points[i], ctx);
    }
    jsonEndCompactArray(ctx);
    jsonName(ctx, "edge_validity");
    jsonBeginCompactArray(ctx);
    for (uint32 i = 0; i < 16; ++i) {
        uint8_print(&obj->edge_validity[i], ctx);
    }
    jsonEndCompactArray(ctx);
    jsonName(ctx, "number_of_deform_points");
    uint16_print(&obj->number_of_deform_points, ctx);
    jsonName(ctx, "active");
    uint16_print(&obj->active, ctx);
    jsonName(ctx, "vertices3D_local");
    jsonBeginCompactArray(ctx);
    for (uint32 i = 0; i < 48; ++i) {
        float32_print(&obj->vertices3D_local[i], ctx);
    }
    jsonEndCompactArray(ctx);
    jsonName(ctx, "triangle_indices");
    jsonBeginCompactArray(ctx);
    for (uint32 i = 0; i < 42; ++i) {
        uint8_print(&obj->triangle_indices[i], ctx);
    }
    jsonEndCompactArray(ctx);
    jsonName(ctx, "number_of_triangles");
    uint16_print(&obj->number_of_triangles, ctx);
    jsonName(ctx, "bounding_box_local");
    AxisAlignedBoundingBox_print(&obj->bounding_box_local, ctx);
    jsonName(ctx, "center_local");
    jsonBeginCompactArray(ctx);
    for (uint32 i = 0; i < 3; ++i) {
        float32_print(&obj->center_local[i], ctx);
    }
    jsonEndCompactArray(ctx);
