void Array_WheelHardpoint_init(Array_WheelHardpoint *obj) {
    obj->type_info_ = &Array_WheelHardpoint_TI;
    obj->count = 0;
    obj->items = NULL;
}

bool Array_WheelHardpoint_read(Array_WheelHardpoint *obj, Buffer* buffer) {
    uint32 count = 0;
    uint32 unk0 = 0;
    uint32 offset = 0;
    uint32 unk1 = 0;
    if (!uint32_read(&offset, buffer)) return false;
    if (!uint32_read(&unk0, buffer)) return false;
    if (!uint32_read(&count, buffer)) return false;
    if (!uint32_read(&unk1, buffer)) return false;
    obj->count = count;
    if(count>0){
       int64 original_offset = 0;
       obj->items = (WheelHardpoint*)mp_calloc(sizeof(WheelHardpoint), count);
       if(buffer->get_position(buffer, &original_offset)!=BUFFER_SUCCESS) return false;
       if(buffer->set_position(buffer, offset, BUFFER_ORIGIN_START)!=BUFFER_SUCCESS) return false;
       for (uint32 i = 0; i < count; ++i) {
           WheelHardpoint_init(&obj->items[i]);
           WheelHardpoint_read(&obj->items[i], buffer);
       }
       if(buffer->set_position(buffer, original_offset, BUFFER_ORIGIN_START)!=BUFFER_SUCCESS) return false;
    }
    return true;
}

void Array_WheelHardpoint_free(Array_WheelHardpoint *obj) {
    mp_free(obj->items);
}

void Array_WheelHardpoint_print(Array_WheelHardpoint *obj, JsonContext* ctx) {
    jsonBeginArray(ctx);
    for (uint32 i = 0; i < obj->count; ++i) {
        WheelHardpoint_print(&obj->items[i], ctx);
    }
    jsonEndArray(ctx);
}

