void Array_AerodynamicSurface_init(Array_AerodynamicSurface *obj) {
    obj->type_info_ = &Array_AerodynamicSurface_TI;
    obj->count = 0;
    obj->items = NULL;
}

bool Array_AerodynamicSurface_read(Array_AerodynamicSurface *obj, Buffer* buffer) {
    uint32 count = 0;
    uint32 unk0 = 0;
    uint32 offset = 0;
    uint32 unk1 = 0;
    if (!uint32_read(&offset, buffer)) return false;
    if (!uint32_read(&unk0, buffer)) return false;
    if (!uint32_read(&count, buffer)) return false;
    if (!uint32_read(&unk1, buffer)) return false;
    obj->count = count;
    if(count>0){
       int64 original_offset = 0;
       obj->items = (AerodynamicSurface*)mp_calloc(sizeof(AerodynamicSurface), count);
       if(buffer->get_position(buffer, &original_offset)!=BUFFER_SUCCESS) return false;
       if(buffer->set_position(buffer, offset, BUFFER_ORIGIN_START)!=BUFFER_SUCCESS) return false;
       for (uint32 i = 0; i < count; ++i) {
           AerodynamicSurface_init(&obj->items[i]);
           AerodynamicSurface_read(&obj->items[i], buffer);
       }
       if(buffer->set_position(buffer, original_offset, BUFFER_ORIGIN_START)!=BUFFER_SUCCESS) return false;
    }
    return true;
}

void Array_AerodynamicSurface_free(Array_AerodynamicSurface *obj) {
    for (uint32 i = 0; i < obj->count; ++i) {
        AerodynamicSurface_free(&obj->items[i]);
    }
    mp_free(obj->items);
}

void Array_AerodynamicSurface_print(Array_AerodynamicSurface *obj, JsonContext* ctx) {
    jsonBeginArray(ctx);
    for (uint32 i = 0; i < obj->count; ++i) {
        AerodynamicSurface_print(&obj->items[i], ctx);
    }
    jsonEndArray(ctx);
}

