void Array_PhysicsComponentDamageFromPart_init(Array_PhysicsComponentDamageFromPart *obj) {
    obj->type_info_ = &Array_PhysicsComponentDamageFromPart_TI;
    obj->count = 0;
    obj->items = NULL;
}

bool Array_PhysicsComponentDamageFromPart_read(Array_PhysicsComponentDamageFromPart *obj, Buffer* buffer) {
    uint32 count = 0;
    uint32 unk0 = 0;
    uint32 offset = 0;
    uint32 unk1 = 0;
    if (!uint32_read(&offset, buffer)) return false;
    if (!uint32_read(&unk0, buffer)) return false;
    if (!uint32_read(&count, buffer)) return false;
    if (!uint32_read(&unk1, buffer)) return false;
    obj->count = count;
    if(count>0){
       int64 original_offset = 0;
       obj->items = (PhysicsComponentDamageFromPart*)mp_calloc(sizeof(PhysicsComponentDamageFromPart), count);
       if(buffer->get_position(buffer, &original_offset)!=BUFFER_SUCCESS) return false;
       if(buffer->set_position(buffer, offset, BUFFER_ORIGIN_START)!=BUFFER_SUCCESS) return false;
       for (uint32 i = 0; i < count; ++i) {
           PhysicsComponentDamageFromPart_init(&obj->items[i]);
           PhysicsComponentDamageFromPart_read(&obj->items[i], buffer);
       }
       if(buffer->set_position(buffer, original_offset, BUFFER_ORIGIN_START)!=BUFFER_SUCCESS) return false;
    }
    return true;
}

void Array_PhysicsComponentDamageFromPart_free(Array_PhysicsComponentDamageFromPart *obj) {
    for (uint32 i = 0; i < obj->count; ++i) {
        PhysicsComponentDamageFromPart_free(&obj->items[i]);
    }
    mp_free(obj->items);
}

void Array_PhysicsComponentDamageFromPart_print(Array_PhysicsComponentDamageFromPart *obj, JsonContext* ctx) {
    jsonBeginArray(ctx);
    for (uint32 i = 0; i < obj->count; ++i) {
        PhysicsComponentDamageFromPart_print(&obj->items[i], ctx);
    }
    jsonEndArray(ctx);
}

