void Array_DoorPartProperties_init(Array_DoorPartProperties *obj) {
    obj->type_info_ = &Array_DoorPartProperties_TI;
    obj->count = 0;
    obj->items = NULL;
}

bool Array_DoorPartProperties_read(Array_DoorPartProperties *obj, Buffer* buffer) {
    uint32 count = 0;
    uint32 unk0 = 0;
    uint32 offset = 0;
    uint32 unk1 = 0;
    if (!uint32_read(&offset, buffer)) return false;
    if (!uint32_read(&unk0, buffer)) return false;
    if (!uint32_read(&count, buffer)) return false;
    if (!uint32_read(&unk1, buffer)) return false;
    obj->count = count;
    if(count>0){
       int64 original_offset = 0;
       obj->items = (DoorPartProperties*)mp_calloc(sizeof(DoorPartProperties), count);
       if(buffer->get_position(buffer, &original_offset)!=BUFFER_SUCCESS) return false;
       if(buffer->set_position(buffer, offset, BUFFER_ORIGIN_START)!=BUFFER_SUCCESS) return false;
       for (uint32 i = 0; i < count; ++i) {
           DoorPartProperties_init(&obj->items[i]);
           DoorPartProperties_read(&obj->items[i], buffer);
       }
       if(buffer->set_position(buffer, original_offset, BUFFER_ORIGIN_START)!=BUFFER_SUCCESS) return false;
    }
    return true;
}

void Array_DoorPartProperties_free(Array_DoorPartProperties *obj) {
    for (uint32 i = 0; i < obj->count; ++i) {
        DoorPartProperties_free(&obj->items[i]);
    }
    mp_free(obj->items);
}

void Array_DoorPartProperties_print(Array_DoorPartProperties *obj, JsonContext* ctx) {
    jsonBeginArray(ctx);
    for (uint32 i = 0; i < obj->count; ++i) {
        DoorPartProperties_print(&obj->items[i], ctx);
    }
    jsonEndArray(ctx);
}

