void Array_StorageLevel_init(Array_StorageLevel *obj) {
    obj->type_info_ = &Array_StorageLevel_TI;
    obj->count = 0;
    obj->items = NULL;
}

bool Array_StorageLevel_read(Array_StorageLevel *obj, Buffer* buffer) {
    uint32 count = 0;
    uint32 unk0 = 0;
    uint32 offset = 0;
    uint32 unk1 = 0;
    if (!uint32_read(&offset, buffer)) return false;
    if (!uint32_read(&unk0, buffer)) return false;
    if (!uint32_read(&count, buffer)) return false;
    if (!uint32_read(&unk1, buffer)) return false;
    obj->count = count;
    if(count>0){
       int64 original_offset = 0;
       obj->items = (StorageLevel*)mp_calloc(sizeof(StorageLevel), count);
       if(buffer->get_position(buffer, &original_offset)!=BUFFER_SUCCESS) return false;
       if(buffer->set_position(buffer, offset, BUFFER_ORIGIN_START)!=BUFFER_SUCCESS) return false;
       for (uint32 i = 0; i < count; ++i) {
           StorageLevel_init(&obj->items[i]);
           StorageLevel_read(&obj->items[i], buffer);
       }
       if(buffer->set_position(buffer, original_offset, BUFFER_ORIGIN_START)!=BUFFER_SUCCESS) return false;
    }
    return true;
}

void Array_StorageLevel_free(Array_StorageLevel *obj) {
    for (uint32 i = 0; i < obj->count; ++i) {
        StorageLevel_free(&obj->items[i]);
    }
    mp_free(obj->items);
}

void Array_StorageLevel_print(Array_StorageLevel *obj, JsonContext* ctx) {
    jsonBeginArray(ctx);
    for (uint32 i = 0; i < obj->count; ++i) {
        StorageLevel_print(&obj->items[i], ctx);
    }
    jsonEndArray(ctx);
}

