void Array_HunterMission_init(Array_HunterMission *obj) {
    obj->type_info_ = &Array_HunterMission_TI;
    obj->count = 0;
    obj->items = NULL;
}

bool Array_HunterMission_read(Array_HunterMission *obj, Buffer* buffer) {
    uint32 count = 0;
    uint32 unk0 = 0;
    uint32 offset = 0;
    uint32 unk1 = 0;
    if (!uint32_read(&offset, buffer)) return false;
    if (!uint32_read(&unk0, buffer)) return false;
    if (!uint32_read(&count, buffer)) return false;
    if (!uint32_read(&unk1, buffer)) return false;
    obj->count = count;
    if(count>0){
       int64 original_offset = 0;
       obj->items = (HunterMission*)mp_calloc(sizeof(HunterMission), count);
       if(buffer->get_position(buffer, &original_offset)!=BUFFER_SUCCESS) return false;
       if(buffer->set_position(buffer, offset, BUFFER_ORIGIN_START)!=BUFFER_SUCCESS) return false;
       for (uint32 i = 0; i < count; ++i) {
           HunterMission_init(&obj->items[i]);
           HunterMission_read(&obj->items[i], buffer);
       }
       if(buffer->set_position(buffer, original_offset, BUFFER_ORIGIN_START)!=BUFFER_SUCCESS) return false;
    }
    return true;
}

void Array_HunterMission_free(Array_HunterMission *obj) {
    for (uint32 i = 0; i < obj->count; ++i) {
        HunterMission_free(&obj->items[i]);
    }
    mp_free(obj->items);
}

void Array_HunterMission_print(Array_HunterMission *obj, JsonContext* ctx) {
    jsonBeginArray(ctx);
    for (uint32 i = 0; i < obj->count; ++i) {
        HunterMission_print(&obj->items[i], ctx);
    }
    jsonEndArray(ctx);
}

