void Array_TextureBlend_init(Array_TextureBlend *obj) {
    obj->type_info_ = &Array_TextureBlend_TI;
    obj->count = 0;
    obj->items = NULL;
}

bool Array_TextureBlend_read(Array_TextureBlend *obj, Buffer* buffer) {
    uint32 count = 0;
    uint32 unk0 = 0;
    uint32 offset = 0;
    uint32 unk1 = 0;
    if (!uint32_read(&offset, buffer)) return false;
    if (!uint32_read(&unk0, buffer)) return false;
    if (!uint32_read(&count, buffer)) return false;
    if (!uint32_read(&unk1, buffer)) return false;
    obj->count = count;
    if(count>0){
       int64 original_offset = 0;
       obj->items = (TextureBlend*)mp_calloc(sizeof(TextureBlend), count);
       if(buffer->get_position(buffer, &original_offset)!=BUFFER_SUCCESS) return false;
       if(buffer->set_position(buffer, offset, BUFFER_ORIGIN_START)!=BUFFER_SUCCESS) return false;
       for (uint32 i = 0; i < count; ++i) {
           TextureBlend_init(&obj->items[i]);
           TextureBlend_read(&obj->items[i], buffer);
       }
       if(buffer->set_position(buffer, original_offset, BUFFER_ORIGIN_START)!=BUFFER_SUCCESS) return false;
    }
    return true;
}

void Array_TextureBlend_free(Array_TextureBlend *obj) {
    for (uint32 i = 0; i < obj->count; ++i) {
        TextureBlend_free(&obj->items[i]);
    }
    mp_free(obj->items);
}

void Array_TextureBlend_print(Array_TextureBlend *obj, JsonContext* ctx) {
    jsonBeginArray(ctx);
    for (uint32 i = 0; i < obj->count; ++i) {
        TextureBlend_print(&obj->items[i], ctx);
    }
    jsonEndArray(ctx);
}

