void Array_ResourceStorageItem_init(Array_ResourceStorageItem *obj) {
    obj->type_info_ = &Array_ResourceStorageItem_TI;
    obj->count = 0;
    obj->items = NULL;
}

bool Array_ResourceStorageItem_read(Array_ResourceStorageItem *obj, Buffer* buffer) {
    uint32 count = 0;
    uint32 unk0 = 0;
    uint32 offset = 0;
    uint32 unk1 = 0;
    if (!uint32_read(&offset, buffer)) return false;
    if (!uint32_read(&unk0, buffer)) return false;
    if (!uint32_read(&count, buffer)) return false;
    if (!uint32_read(&unk1, buffer)) return false;
    obj->count = count;
    if(count>0){
       int64 original_offset = 0;
       obj->items = (ResourceStorageItem*)mp_calloc(sizeof(ResourceStorageItem), count);
       if(buffer->get_position(buffer, &original_offset)!=BUFFER_SUCCESS) return false;
       if(buffer->set_position(buffer, offset, BUFFER_ORIGIN_START)!=BUFFER_SUCCESS) return false;
       for (uint32 i = 0; i < count; ++i) {
           ResourceStorageItem_init(&obj->items[i]);
           ResourceStorageItem_read(&obj->items[i], buffer);
       }
       if(buffer->set_position(buffer, original_offset, BUFFER_ORIGIN_START)!=BUFFER_SUCCESS) return false;
    }
    return true;
}

void Array_ResourceStorageItem_free(Array_ResourceStorageItem *obj) {
    mp_free(obj->items);
}

