void CharacterProfile1_init(CharacterProfile1 *obj) {
    obj->type_info_ = &CharacterProfile1_TI;
    CharacterLooks_init(&obj->CharacterLooks);
    Array_OwnedEquipment1_init(&obj->Inventory);
    Array_VehicleData_init(&obj->VehicleData);
    Array_uint32_init(&obj->EmotesUnlocked);
    Array_uint64_init(&obj->Collectables);
    Array_PlayerPosition_init(&obj->PlayerPositions);
    Array_uint32_init(&obj->GivenDLCItems);
}

bool CharacterProfile1_read(CharacterProfile1 *obj, Buffer* buffer) {
    CharacterLooks_read(&obj->CharacterLooks, buffer);
    for(int i = 0; i < 128; ++i) {
        uint32_read(&obj->Skills[i], buffer);
    }
    for(int i = 0; i < 128; ++i) {
        uint8_read(&obj->SkillLevel[i], buffer);
    }
    for(int i = 0; i < 16; ++i) {
        uint32_read(&obj->SkillPointsSpent[i], buffer);
    }
    uint32_read(&obj->SkillPoints, buffer);
    uint32_read(&obj->ActiveSkill, buffer);
    uint32_read(&obj->Xp, buffer);
    uint16_read(&obj->Level, buffer);
    uint8_read(&obj->Created, buffer);
    buffer->skip(buffer, 1);
    Array_OwnedEquipment1_read(&obj->Inventory, buffer);
    for(int i = 0; i < 16; ++i) {
        uint32_read(&obj->PPInventorySlot[i], buffer);
    }
    Array_VehicleData_read(&obj->VehicleData, buffer);
    uint8_read(&obj->VehiclePreferedCameraThirdPerson, buffer);
    uint8_read(&obj->BackpackSizeColumns, buffer);
    uint8_read(&obj->BackpackSizeRows, buffer);
    buffer->skip(buffer, 5);
    Array_uint32_read(&obj->EmotesUnlocked, buffer);
    for(int i = 0; i < 8; ++i) {
        uint32_read(&obj->EmoteSlots[i], buffer);
    }
    Array_uint64_read(&obj->Collectables, buffer);
    float32_read(&obj->DistanceTravelled, buffer);
    float32_read(&obj->TimeOfDay, buffer);
    float32_read(&obj->WeatherTime, buffer);
    buffer->skip(buffer, 4);
    Array_PlayerPosition_read(&obj->PlayerPositions, buffer);
    uint64_read(&obj->LastLevelUpTS, buffer);
    Array_uint32_read(&obj->GivenDLCItems, buffer);
    return true;
}

