void Array_CompanionData1_init(Array_CompanionData1 *obj) {
    obj->type_info_ = &Array_CompanionData1_TI;
    obj->count = 0;
    obj->items = NULL;
}

bool Array_CompanionData1_read(Array_CompanionData1 *obj, Buffer* buffer) {
    uint32 count = 0;
    uint32 unk0 = 0;
    uint32 offset = 0;
    uint32 unk1 = 0;
    if (!uint32_read(&offset, buffer)) return false;
    if (!uint32_read(&unk0, buffer)) return false;
    if (!uint32_read(&count, buffer)) return false;
    if (!uint32_read(&unk1, buffer)) return false;
    obj->count = count;
    if(count>0){
       int64 original_offset = 0;
       obj->items = (CompanionData1*)mp_calloc(sizeof(CompanionData1), count);
       if(buffer->get_position(buffer, &original_offset)!=BUFFER_SUCCESS) return false;
       if(buffer->set_position(buffer, offset, BUFFER_ORIGIN_START)!=BUFFER_SUCCESS) return false;
       for (uint32 i = 0; i < count; ++i) {
           CompanionData1_init(&obj->items[i]);
           CompanionData1_read(&obj->items[i], buffer);
       }
       if(buffer->set_position(buffer, original_offset, BUFFER_ORIGIN_START)!=BUFFER_SUCCESS) return false;
    }
    return true;
}

void Array_CompanionData1_free(Array_CompanionData1 *obj) {
    for (uint32 i = 0; i < obj->count; ++i) {
        CompanionData1_free(&obj->items[i]);
    }
    mp_free(obj->items);
}

