void Array_ControlPointSaveData1_init(Array_ControlPointSaveData1 *obj) {
    obj->type_info_ = &Array_ControlPointSaveData1_TI;
    obj->count = 0;
    obj->items = NULL;
}

bool Array_ControlPointSaveData1_read(Array_ControlPointSaveData1 *obj, Buffer* buffer) {
    uint32 count = 0;
    uint32 unk0 = 0;
    uint32 offset = 0;
    uint32 unk1 = 0;
    if (!uint32_read(&offset, buffer)) return false;
    if (!uint32_read(&unk0, buffer)) return false;
    if (!uint32_read(&count, buffer)) return false;
    if (!uint32_read(&unk1, buffer)) return false;
    obj->count = count;
    if(count>0){
       int64 original_offset = 0;
       obj->items = (ControlPointSaveData1*)mp_calloc(sizeof(ControlPointSaveData1), count);
       if(buffer->get_position(buffer, &original_offset)!=BUFFER_SUCCESS) return false;
       if(buffer->set_position(buffer, offset, BUFFER_ORIGIN_START)!=BUFFER_SUCCESS) return false;
       for (uint32 i = 0; i < count; ++i) {
           ControlPointSaveData1_init(&obj->items[i]);
           ControlPointSaveData1_read(&obj->items[i], buffer);
       }
       if(buffer->set_position(buffer, original_offset, BUFFER_ORIGIN_START)!=BUFFER_SUCCESS) return false;
    }
    return true;
}

void Array_ControlPointSaveData1_free(Array_ControlPointSaveData1 *obj) {
    for (uint32 i = 0; i < obj->count; ++i) {
        ControlPointSaveData1_free(&obj->items[i]);
    }
    mp_free(obj->items);
}

