void WindowConstants_init(WindowConstants *obj) {
    obj->type_info_ = &WindowConstants_TI;
}

bool WindowConstants_read(WindowConstants *obj, Buffer* buffer) {
    float32_read(&obj->SpecGloss, buffer);
    float32_read(&obj->SpecFresnel, buffer);
    float32_read(&obj->DiffuseRoughness, buffer);
    float32_read(&obj->TintPower, buffer);
    float32_read(&obj->TintMultiplier, buffer);
    float32_read(&obj->MinAlpha, buffer);
    float32_read(&obj->UVScale, buffer);
    float32_read(&obj->ChromaticAberration, buffer);
    float32_read(&obj->RefractionStrength, buffer);
{
        uint8 bitfield_value = 0;
        uint8_read(&bitfield_value, buffer);
        obj->Simple = (bitfield_value >> 0) & 0x1;
        obj->OneSided = (bitfield_value >> 1) & 0x1;
        obj->LensOcclusion = (bitfield_value >> 2) & 0x1;
}
    buffer->skip(buffer, 3);
    return true;
}

