void Array_SchematicTree_init(Array_SchematicTree *obj) {
    obj->type_info_ = &Array_SchematicTree_TI;
    obj->count = 0;
    obj->items = NULL;
}

bool Array_SchematicTree_read(Array_SchematicTree *obj, Buffer* buffer) {
    uint32 count = 0;
    uint32 unk0 = 0;
    uint32 offset = 0;
    uint32 unk1 = 0;
    if (!uint32_read(&offset, buffer)) return false;
    if (!uint32_read(&unk0, buffer)) return false;
    if (!uint32_read(&count, buffer)) return false;
    if (!uint32_read(&unk1, buffer)) return false;
    obj->count = count;
    if(count>0){
       int64 original_offset = 0;
       obj->items = (SchematicTree*)mp_calloc(sizeof(SchematicTree), count);
       if(buffer->get_position(buffer, &original_offset)!=BUFFER_SUCCESS) return false;
       if(buffer->set_position(buffer, offset, BUFFER_ORIGIN_START)!=BUFFER_SUCCESS) return false;
       for (uint32 i = 0; i < count; ++i) {
           SchematicTree_init(&obj->items[i]);
           SchematicTree_read(&obj->items[i], buffer);
       }
       if(buffer->set_position(buffer, original_offset, BUFFER_ORIGIN_START)!=BUFFER_SUCCESS) return false;
    }
    return true;
}

void Array_SchematicTree_free(Array_SchematicTree *obj) {
    for (uint32 i = 0; i < obj->count; ++i) {
        SchematicTree_free(&obj->items[i]);
    }
    mp_free(obj->items);
}

